# Convertido de run_tests.sh por convert_shell_to_powershell.ps1\n\n<#\nEste script foi convertido automaticamente de um script shell (.sh) para PowerShell (.ps1).\nAlgumas conversões comuns foram aplicadas, mas é provável que seja necessário ajuste manual.\n\nConversões aplicadas automaticamente:\n- Comentários (# -> #)\n- Variáveis básicas ( -> \)\n\nVerifique e ajuste manualmente:\n- Comandos específicos do Linux (ls, grep, etc.) para equivalentes do PowerShell\n- Redirecionamentos de saída (>, >>, |)\n- Estruturas de controle (if, for, while)\n- Execução de comandos em sequência (;, &&, ||)\n#>\n\n# #!/bin/bash\n\n# Script para executar testes de performance do módulo Citizenship\n\n# Configurações\nLOCUSTFILE="citizenship_load_test.py"\nHOST="http://localhost:8000"\nUSERS="17"  # Total de usuários (10 CitizenTestUser + 5 AtestadoTestUser + 2 ReportTestUser)\nSPAWN_RATE="3.5"  # Taxa de spawn (2 + 1 + 0.5)\nDURATION="5m"  # 5 minutos\nREPORT_DIR="reports"\nTIMESTAMP=$(date +"%Y%m%d_%H%M%S")\n\n# Cria diretório de relatórios se não existir\nNew-Item -Path "$REPORT_DIR" -ItemType Directory -Force | Out-Null\n\nWrite-Host "🚀 Iniciando testes de performance para o módulo Citizenship..."\nWrite-Host "📊 Usuários: $USERS"\nWrite-Host "⏱️  Duração: $DURATION"\nWrite-Host "📂 Diretório de relatórios: $REPORT_DIR"\n\n# Executa o teste\nlocust -f "$LOCUSTFILE" /\n  --host="$HOST" /\n  --headless /\n  --users="$USERS" /\n  --spawn-rate="$SPAWN_RATE" /\n  --run-time="$DURATION" /\n  --csv="$REPORT_DIR/performance_$TIMESTAMP" /\n  --html="$REPORT_DIR/performance_report_$TIMESTAMP.html"\n\n# Verifica se o teste foi executado com sucesso\nif [ $? -eq 0 ]; then\nWrite-Host "✅ Testes de performance concluídos com sucesso!"\nWrite-Host "📊 Relatório gerado em: $REPORT_DIR/performance_report_$TIMESTAMP.html"\nelse\nWrite-Host "❌ Ocorreu um erro durante a execução dos testes."\n  exit 1\nfi\n\n\n# Fim do script convertido\n
